select '00000000-0000-4000-b000-000000000003', 'paso-tus-documentos-a-pdf-y-los-ordeno-en-carpetas-d003', '00000000-0000-4000-a000-000000000006', 'offer', 'Paso tus documentos a PDF y los ordeno en carpetas', 'Me envías las fotos o escaneos por el chat y te devuelvo PDF limpios, con nombres claros y ordenados por carpetas. Ideal para tener a mano facturas, contratos y recibos.', c.id, s.id, m.id, 'online', 1000, 'fixed', false, array['pdf', 'documentos', 'orden']::text[], 'published', 'approved', now() - interval '3 days 2 minutes', now() - interval '3 days' + interval '30 days', now() - interval '3 days 2 minutes'
