select '00000000-0000-4000-b000-000000000004', 'acompanamiento-a-citas-medicas-y-analisis-d004', '00000000-0000-4000-a000-000000000007', 'offer', 'Acompañamiento a citas médicas y análisis', 'Acompaño a personas mayores al centro de salud, al hospital o a hacerse análisis. Espero con ellas, tomo nota de lo que dice el médico si lo necesitan y las dejo en casa. Experiencia como auxiliar de enfermería.', c.id, s.id, m.id, 'in_person', 1200, 'hourly', false, array['hospital', 'centro de salud']::text[], 'published', 'approved', now() - interval '5 days 3 minutes', now() - interval '5 days' + interval '30 days', now() - interval '5 days 3 minutes'
