select '00000000-0000-4000-b000-000000000045', 'textos-para-tu-web-o-blog-d045', '00000000-0000-4000-a000-000000000025', 'offer', 'Textos para tu web o blog', 'Escribo los textos de tu web o artículos de blog claros y pensados para buscadores. Precio por cada 600 palabras.', c.id, s.id, m.id, 'online', 4000, 'fixed', false, array['redacción', 'blog']::text[], 'published', 'approved', now() - interval '15 days 44 minutes', now() - interval '15 days' + interval '30 days', now() - interval '15 days 44 minutes'
