select '00000000-0000-4000-b000-000000000047', 'copias-de-seguridad-automaticas-para-que-no-pierdas-nada-d047', '00000000-0000-4000-a000-000000000028', 'offer', 'Copias de seguridad automáticas para que no pierdas nada', 'Configuro copias automáticas de tu ordenador y del móvil en la nube o en un disco externo, y te enseño a recuperar archivos.', c.id, s.id, m.id, 'online', 2500, 'fixed', false, array['copias', 'nube']::text[], 'published', 'approved', now() - interval '9 days 46 minutes', now() - interval '9 days' + interval '30 days', now() - interval '9 days 46 minutes'
