select '00000000-0000-4000-b000-000000000048', 'video-resumen-de-una-boda-con-musica-d048', '00000000-0000-4000-a000-000000000029', 'request', 'Vídeo resumen de una boda con música', 'Tengo unos 200 clips de móvil de la boda de mi hermana y quiero un vídeo resumen de 5 minutos con música.', c.id, s.id, m.id, 'online', 5000, 'fixed', false, array['vídeo', 'boda']::text[], 'published', 'approved', now() - interval '10 days 47 minutes', now() - interval '10 days' + interval '30 days', now() - interval '10 days 47 minutes'
